
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_rpw86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_rpw86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.320216873694675e+00, -4.240603044209071e+00, -4.129310479937011e+00, -3.975675940849507e+00, -3.767370636766914e+00, -3.492046317734579e+00, -3.140727568361058e+00, -2.712577274340054e+00, -2.218250878729037e+00, -1.678973495305565e+00, -1.128767745580638e+00, -7.157475667235116e-01, -6.017891474570897e-01, -5.096924734599075e-01, -3.843181617140399e-01, -2.520276546263017e-01, -1.403504815510176e-01, -6.439232904338080e-02, -2.409550913974066e-02, -6.420109109499789e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


